// Wildbound: a compact, touch-friendly voxel survival sandbox.
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const $=id=>document.getElementById(id), scene=new THREE.Scene();
scene.background=new THREE.Color(0xb9d7c7); scene.fog=new THREE.Fog(0xb9d7c7,42,105);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,180);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.8)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.12; $('game').appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xe8f5e8,0x829272,2.1));
const sun=new THREE.DirectionalLight(0xffedcc,3.2); sun.position.set(-24,38,20); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-42;sun.shadow.camera.right=42;sun.shadow.camera.top=42;sun.shadow.camera.bottom=-42;sun.shadow.bias=-.0003;scene.add(sun);
const mat=(color,rough=.92)=>new THREE.MeshStandardMaterial({color,roughness:rough});
const mats={grass:mat(0x84a86e),grass2:mat(0x90b178),soil:mat(0x9b8661),path:mat(0xcbb98d),bark:mat(0x795b3b),leaf:mat(0x4f8052),leaf2:mat(0x6f9858),stone:mat(0x898e83),berry:mat(0x536d46),blue:mat(0x566d61),cream:mat(0xf1dfb8),red:mat(0xd78862),dark:mat(0x394b40)};
const boxGeo=new THREE.BoxGeometry(1,1,1), cylGeo=new THREE.CylinderGeometry(.5,.5,1,8), sphereGeo=new THREE.SphereGeometry(.5,10,8);
function cube(parent,m,x,y,z,sx,sy,sz){const o=new THREE.Mesh(boxGeo,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function groupAt(x,z){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);return g}
// Soft rolling country floor and an old trade trail.
const floor=new THREE.Mesh(new THREE.PlaneGeometry(180,180),mats.grass);floor.rotation.x=-Math.PI/2;floor.position.y=-.12;floor.receiveShadow=true;scene.add(floor);
const rand=(()=>{let s=41917;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}})();
// A winding dirt road leads from the homestead to the market.
for(let i=0;i<30;i++){const t=i/29,x=2+10*t,z=3-9*t;const p=cube(scene,mats.path,x,-.055,z,2.8+rand()*1.1,.035,2.05);p.rotation.y=-.74+(rand()-.5)*.12}
// Wild grass tufts and flowers break up the clearings.
for(let i=0;i<380;i++){const x=(rand()-.5)*86,z=(rand()-.5)*86;if(Math.hypot(x,z)<5||Math.hypot(x-12,z+6)<7)continue;const tuft=cube(scene,rand()>.5?mats.grass2:mats.leaf2,x,-.015,z,.12+rand()*.16,.08+rand()*.18,.12+rand()*.16);tuft.rotation.y=rand()*3}
const entities=[];
function makeTree(x,z,scale=1){const g=groupAt(x,z);cube(g,mats.bark,0,.8*scale,0,.42*scale,1.6*scale,.42*scale);cube(g,mats.leaf,0,1.85*scale,0,1.65*scale,1.15*scale,1.55*scale);cube(g,mats.leaf2,-.18*scale,2.35*scale,.06*scale,1.18*scale,.85*scale,1.18*scale);cube(g,mats.leaf,.2*scale,1.62*scale,.1*scale,1.35*scale,.72*scale,1.3*scale);return g}
for(let i=0;i<92;i++){let x=(rand()-.5)*78,z=(rand()-.5)*78;if(Math.hypot(x,z)<7||Math.hypot(x-12,z+6)<8)continue;makeTree(x,z,.72+rand()*.68)}
function makeNode(kind,x,z){const g=groupAt(x,z);if(kind==='wood'){cube(g,mats.bark,0,.3,0,.95,.42,.48).rotation.z=.22;cube(g,mat(0xb39465),-.2,.32,.01,.23,.46,.5).rotation.z=.22;cube(g,mat(0xb39465),.23,.29,.02,.23,.46,.5).rotation.z=.22}else if(kind==='stone'){const a=cube(g,mats.stone,0,.36,0,.83,.68,.72);a.rotation.set(.1,.35,.2);const b=cube(g,mat(0xa6a99b),.34,.3,.1,.4,.45,.43);b.rotation.y=.7}else{cube(g,mats.berry,0,.36,0,.82,.6,.72);for(let n=0;n<6;n++){const b=new THREE.Mesh(sphereGeo,mat(n%2?0x8c4c68:0x5c7190));b.scale.setScalar(.12);b.position.set((rand()-.5)*.7,.67+rand()*.26,(rand()-.5)*.6);b.castShadow=true;g.add(b)}}
 entities.push({kind,x,z,mesh:g,alive:true});return g}
for(let i=0;i<25;i++){let x=(rand()-.5)*70,z=(rand()-.5)*70;if(Math.hypot(x,z)<6||Math.hypot(x-12,z+6)<7)continue;makeNode(i%3===0?'stone':'wood',x,z)}
for(let i=0;i<17;i++){let x=(rand()-.5)*66,z=(rand()-.5)*66;if(Math.hypot(x,z)<6||Math.hypot(x-12,z+6)<6)continue;makeNode('berry',x,z)}
// Trading post landmark: warm timber, canvas awning, produce crates and sign.
const shop=groupAt(12,-6);cube(shop,mats.bark,0,1.35,0,4.6,2.7,3.5);cube(shop,mat(0x465d4a),0,2.95,0,5.25,.45,4.15);cube(shop,mat(0xe7d6b3),0,2.12,1.79,4.5,.9,.13);cube(shop,mats.red,0,2.76,1.96,4.9,.2,.4);cube(shop,mat(0x6f4934),0,1.12,1.83,1.08,2.2,.18);cube(shop,mat(0xf3dcaa),0,3.45,1.9,2.25,.55,.18);cube(shop,mat(0x52654d),0,3.46,2.02,1.55,.18,.08);
for(let x of [-1.6,1.55])cube(shop,mat(0xc59b68),x,.42,2.3,.8,.82,.7);
// Player character, dressed like a little trail scout.
const player=groupAt(0,0);const skin=mat(0xe0b28d),shirt=mat(0xe18b58),pants=mat(0x405e56),pack=mat(0xc8a065);let body=cube(player,shirt,0,.94,0,.78,.9,.5);cube(player,skin,0,1.68,0,.62,.62,.62);cube(player,mat(0x485b43),0,2.02,0,.76,.2,.75);cube(player,pack,-.48,1.05,-.02,.27,.54,.42);cube(player,pants,-.2,.36,0,.27,.55,.32);cube(player,pants,.2,.36,0,.27,.55,.32);cube(player,skin,0,.75,.34,.45,.17,.1);player.position.set(0,0,0);
let state={wood:8,stone:4,berries:3,coins:24,health:100,food:82,builds:0,day:1,time:8.33,selected:'cabin',buildMode:false,started:false,nearby:null};
let move={x:0,z:0},target=null, last=performance.now(), toastTimer;
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function updateUI(){for(const k of ['wood','stone','berries'])$(k==='berries'?'berryCount':k+'Count').textContent=state[k];$('coins').textContent=state.coins;$('healthNum').textContent=Math.round(state.health);$('foodNum').textContent=Math.round(state.food);$('healthBar').style.width=state.health+'%';$('foodBar').style.width=state.food+'%';$('homeCount').textContent=state.builds;$('clock').textContent=(state.time<18?'☀️ ':'🌙 ')+String(Math.floor(state.time)).padStart(2,'0')+':'+String(Math.floor((state.time%1)*60)).padStart(2,'0');$('brand').classList?.add?.('');$('progressText').innerHTML=state.builds?`Shelter <span>1 / 1</span> · Valley explored <span>${Math.min(100,Math.floor(Math.hypot(player.position.x,player.position.z)*2))}%</span>`:`Shelter <span>0 / 1</span> · timber ${state.wood}/8`;if(state.builds){$('questTitle').textContent='Make yourself at home';$('questText').textContent='Your shelter is up. Explore the valley, keep your energy up, and trade at the post.'}}
function nearest(){let found=null,d=3.3;for(const e of entities){if(!e.alive)continue;const n=Math.hypot(player.position.x-e.x,player.position.z-e.z);if(n<d){found=e;d=n}}const shopD=Math.hypot(player.position.x-12,player.position.z+6);if(shopD<5.4&&shopD<d+1)return {kind:'shop',distance:shopD};return found?{...found,distance:d}:null}
function updateHint(){state.nearby=nearest();const near=state.nearby;if(near?.kind==='shop'){$('hint').textContent='Trading post nearby · press E to browse';$('actionBtn').innerHTML='🪙 &nbsp; TRADE <span>E</span>'}else if(near){$('hint').textContent=`Nearby ${near.kind==='wood'?'fallen timber':near.kind==='stone'?'stone':'wild berries'} · press E to gather`;$('actionBtn').innerHTML='✦ &nbsp; GATHER <span>E</span>'}else{$('hint').textContent=state.buildMode?'Choose a structure, then place it nearby':'WASD to wander · E to gather · B to build';$('actionBtn').innerHTML='✦ &nbsp; GATHER <span>E</span>'}}
function interact(){const n=nearest();if(n?.kind==='shop'){openShop();return}if(n){const type=n.kind,amount=type==='wood'?2:1;state[type]+=amount;n.alive=false;scene.remove(n.mesh);toast(type==='wood'?`Gathered ${amount} timber`:`Gathered ${type==='stone'?'stone':'wild berries'}`);if(type==='berries'){state.food=Math.min(100,state.food+8);toast('Wild berries +8 nourishment')}updateUI();return}if(state.food<28&&state.berries){state.berries--;state.food=Math.min(100,state.food+25);toast('A handful of berries. +25 nourishment');updateUI();return}toast('Nothing close by. Take a little walk!')}

